import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第五十七卦 巽 巽为风 巽上巽下","description":"周易 - 第五十七卦 巽 巽为风 巽上巽下","frontmatter":{"title":"第五十七卦 巽 巽为风 巽上巽下","description":"周易 - 第五十七卦 巽 巽为风 巽上巽下"},"headers":[],"relativePath":"zh/classics/zhouyi/058.md","filePath":"zh/classics/zhouyi/058.md"}'),l={name:"zh/classics/zhouyi/058.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="巽" tabindex="-1">巽 <a class="header-anchor" href="#巽" aria-label="Permalink to “巽”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>小亨，利攸往，利见大人。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>重巽以申命，刚巽乎中正而志行。柔皆顺乎刚，是以小亨，利有攸往，利见大人。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>随风，巽；君子以申命行事。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>进退，利武人之贞。象曰：进退，志疑也。 利武人之贞，志治也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>巽在床下。用史巫纷若，吉无咎。象曰：纷若之吉，得中也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>频巽，吝。象曰：频巽之吝，志穷也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>悔亡，田获三品。象曰：田获三品，有功也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>贞吉悔亡，无不利。无初有终，先庚三日，后庚三日，吉。象曰：九五之吉，位正中也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>巽在床下，丧其资斧，贞凶。象曰：巽在□下，上穷也。丧其资斧，正乎凶也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
